def components(band):
    B=len(band); W=len(band[0]); seen=set(); comp={}
    for r in range(B):
        for c in range(W):
            if band[r][c] and (r,c) not in seen:
                stack=[(r,c)]; cells=[]
                while stack:
                    p=stack.pop()
                    if p in seen: continue
                    seen.add(p); cells.append(p)
                    rr,cc=p
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(rr+dr,cc+dc)
                        if 0<=q[0]<B and 0<=q[1]<W and band[q[0]][q[1]] and q not in seen: stack.append(q)
                for p in cells: comp[p]=cells
    return comp

