def make_shift(shs):  # shs: ((dr1,dc1),(dr2,dc2),(dr3,dc3))
    def f(g):
        b=bands(g); top=b[0]; B=3; W=len(g[0])
        prio={4:0,8:1,2:2}
        out=[row[:] for row in top]
        for r in range(B):
            for c in range(W):
                if top[r][c]==0:
                    cands=[]
                    for k in (1,2,3):
                        dr,dc=shs[k-1]; rr,cc=r+dr,c+dc
                        if 0<=rr<B and 0<=cc<W and b[k][rr][cc]: cands.append(b[k][rr][cc])
                    if cands: out[r][c]=min(cands,key=lambda x:prio[x])
        return out
    return f
